// Extrai dados do payload Meta Cloud API
const body = $json.body ?? $json;
const change = body.entry?.[0]?.changes?.[0]?.value;

// Ignora eventos sem mensagem (ex: status de entrega/leitura)
if (!change?.messages?.length) {
  return [{ json: { skip: true, reason: 'sem_mensagem' } }];
}

const msg = change.messages[0];

// Por enquanto so processa texto; imagens/audio ignorados
if (msg.type !== 'text') {
  return [{ json: { skip: true, reason: 'tipo_nao_suportado_' + msg.type } }];
}

const from = msg.from;
const messageText = msg.text.body;
const messageId = msg.id;
const contactName = change.contacts?.[0]?.profile?.name || from;
const timestamp = msg.timestamp;

return [{ json: { skip: false, from, messageText, messageId, contactName, timestamp } }];

// Combina dados do Parse Payload Meta com horarios do Trinks
const source = $('Parse Payload Meta').item.json;
const trinks = $json;

// Formata horarios vagos de forma legivel para o TESS
let slotsText = 'HORARIOS VAGOS HOJE:\n';
let hasSlots = false;

if (trinks.data && Array.isArray(trinks.data)) {
  for (const prof of trinks.data) {
    if (prof.horariosVagos && prof.horariosVagos.length > 0) {
      hasSlots = true;
      slotsText += `- ${prof.nome}: ${prof.horariosVagos.join(', ')}\n`;
    }
  }
}

if (!hasSlots) {
  slotsText = 'HORARIOS VAGOS HOJE: Nenhum horario disponivel para hoje. Sugira ao cliente verificar outro dia.';
}

return [{ json: { ...source, availableSlots: slotsText } }];

// Extrai o texto da resposta do TESS e detecta tags de booking
const raw = $json;
const source = $('Parse Payload Meta').item.json;

let response = '';

// Tenta diferentes formatos de resposta TESS
if (typeof raw === 'string') {
  response = raw;
} else if (raw.output && typeof raw.output === 'string') {
  response = raw.output;
} else if (raw.choices?.[0]?.message?.content) {
  response = raw.choices[0].message.content;
} else if (raw.response && typeof raw.response === 'string') {
  response = raw.response;
} else if (raw.text && typeof raw.text === 'string') {
  response = raw.text;
} else if (raw.content && typeof raw.content === 'string') {
  response = raw.content;
} else if (Array.isArray(raw.content) && raw.content[0]?.text) {
  response = raw.content[0].text;
}

if (!response) {
  response = 'Ola! Estou com uma dificuldade tecnica no momento. Nosso atendimento humano entrara em contato em breve. Obrigado!';
}

response = response.trim();

// Detecta tags de booking
let bookingRequest = null;
let bookingConfirm = null;
let clientMessage = response;

// Detecta [BOOKING_REQUEST]
const reqMatch = response.match(/\[BOOKING_REQUEST\]\s*\n?({[\s\S]*?})/i);
if (reqMatch) {
  try {
    bookingRequest = JSON.parse(reqMatch[1]);
    clientMessage = response.replace(/\[BOOKING_REQUEST\]\s*\n?{[\s\S]*?}/i, '').trim();
  } catch (e) { /* ignora parse error */ }
}

// Detecta [BOOKING_CONFIRM]
const confMatch = response.match(/\[BOOKING_CONFIRM\]\s*\n?({[\s\S]*?})/i);
if (confMatch) {
  try {
    bookingConfirm = JSON.parse(confMatch[1]);
    clientMessage = response.replace(/\[BOOKING_CONFIRM\]\s*\n?{[\s\S]*?}/i, '').trim();
  } catch (e) { /* ignora parse error */ }
}

// Se nao sobrou mensagem para o cliente apos remover tags, manter a original
if (!clientMessage) {
  clientMessage = response;
}

return [{ json: {
  ...source,
  tessResponse: clientMessage,
  bookingRequest,
  bookingConfirm,
  hasBookingAction: !!(bookingRequest || bookingConfirm)
} }];

// Processa acao de booking na API Trinks
const data = $json;
const TRINKS_API = 'https://api.trinks.com/v1';
const TRINKS_KEY = 'O808z7HPzj4zFP0Y0j303xo4w315F2P6QslLUrr7';

let bookingResult = null;
let bookingError = null;

try {
  if (data.bookingRequest && data.bookingRequest.action === 'check_availability') {
    // Busca horarios para a data solicitada
    const date = data.bookingRequest.date;
    const resp = await fetch(`${TRINKS_API}/agendamentos/profissionais/${date}`, {
      headers: {
        'X-Api-Key': TRINKS_KEY,
        'estabelecimentoId': '243868'
      }
    });
    const result = await resp.json();

    let slotsText = `HORARIOS VAGOS PARA ${date}:\n`;
    let hasSlots = false;

    if (result.data && Array.isArray(result.data)) {
      for (const prof of result.data) {
        // Filtra por profissional se especificado
        if (data.bookingRequest.professional_id && prof.id !== data.bookingRequest.professional_id) continue;
        if (prof.horariosVagos && prof.horariosVagos.length > 0) {
          hasSlots = true;
          slotsText += `- ${prof.nome}: ${prof.horariosVagos.join(', ')}\n`;
        }
      }
    }

    if (!hasSlots) {
      slotsText += 'Nenhum horario disponivel para esta data.';
    }

    bookingResult = { type: 'availability', slots: slotsText };

  } else if (data.bookingConfirm && data.bookingConfirm.action === 'create_booking') {
    // Por enquanto: registra intencao de booking (POST requer ServicoEstabelecimentoId)
    // TODO: Mapear servicos via GET /v1/servicos quando IDs forem coletados
    bookingResult = {
      type: 'booking_pending',
      message: `Agendamento registrado para ${data.bookingConfirm.client_name}: ${data.bookingConfirm.service_name} em ${data.bookingConfirm.date_time} com profissional ID ${data.bookingConfirm.professional_id}. NOTA: Booking automatico pendente — ServicoEstabelecimentoId necessario.`
    };
  }
} catch (err) {
  bookingError = err.message;
}

return [{ json: {
  ...data,
  bookingResult,
  bookingError,
  // Se temos novos slots, precisamos chamar TESS novamente com o contexto
  needsSecondCall: bookingResult?.type === 'availability'
} }];

