// Extrai resposta da 2a chamada TESS (com horarios)
const raw = $json;
const source = $('Parse Payload Meta').item.json;

let response = '';
if (typeof raw === 'string') response = raw;
else if (raw.output) response = raw.output;
else if (raw.choices?.[0]?.message?.content) response = raw.choices[0].message.content;
else if (raw.response) response = raw.response;
else if (raw.text) response = raw.text;
else if (raw.content && typeof raw.content === 'string') response = raw.content;
else if (Array.isArray(raw.content) && raw.content[0]?.text) response = raw.content[0].text;

if (!response) response = 'Vou verificar os horarios disponiveis e ja te retorno!';

// Remove eventuais tags de booking da resposta
response = response.replace(/\[BOOKING_REQUEST\]\s*\n?{[\s\S]*?}/gi, '').trim();
response = response.replace(/\[BOOKING_CONFIRM\]\s*\n?{[\s\S]*?}/gi, '').trim();

return [{ json: { ...source, tessResponse: response } }];

